// План specs/google-maps-mobile.md 1.5 (кейс GM-05). Admin, компания «test». Только просмотр.
// Десктоп 1440 без изменений (комментарий программиста): ссылок навигации нет, «View on Map» не вызывает window.open.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from '../addresses/address-helpers';
import { TEST_CLIENT_ID } from '../addresses/address-display-helpers';
import {
  TEST_LEAD, gmapsDirLinks, leadCard, openJobPreview, openLeadDetails, openLeadsMap, openedUrls, trapExternalMaps,
} from '../leads-map/map-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Десктоп: адреса без перехода в Google Maps (#6e6f101d)', () => {
  test('Desktop 1440: no Google Maps directions links on Map, Lead Details, Job Preview, client header; "View on Map" stays in the site #6e6f101d @desktop @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await trapExternalMaps(page);

    // Map: адрес в карточке — текст, не ссылка; «View on Map» без window.open.
    await openLeadsMap(page);
    const card = leadCard(page, TEST_LEAD.name, TEST_LEAD.phone);
    await expect(card).toContainText(TEST_LEAD.address);
    await expect(gmapsDirLinks(page.locator('main'))).toHaveCount(0);
    await page.getByRole('button', { name: 'View on Map' }).first().click();
    await expect(page).toHaveURL(/\/map$/);
    expect(await openedUrls(page), 'window.open на десктопе').toEqual([]);

    // Lead Details: адрес есть, ссылки нет.
    const leadDialog = await openLeadDetails(page, TEST_LEAD.phone);
    await expect(leadDialog).toContainText(TEST_LEAD.address);
    await expect(gmapsDirLinks(leadDialog)).toHaveCount(0);

    // Job Preview: адрес есть, ссылки нет.
    const jobDialog = await openJobPreview(page, 'Completed', 'JOB-0011');
    await expect(jobDialog).toContainText('2221 NW Federal Hwy');
    await expect(gmapsDirLinks(jobDialog)).toHaveCount(0);

    // Шапка клиента: адрес есть, ссылки нет.
    await page.goto(`/CustomerDetail?id=${TEST_CLIENT_ID}`);
    await expect(page.locator('main')).toContainText('2221 NW Federal Hwy');
    await expect(gmapsDirLinks(page.locator('main'))).toHaveCount(0);
  });
});
